Definition kn_havocF (bc : bctx) (ub : expr) (uk : Z) (un : expr) : list kentry :=
  let sp := mk_sprepB bc ub uk un in
  let m1o := mk_m1o bc ub un in
  List.flat_map (havoc1pF bc sp m1o ub uk un) (bc_fk bc).
